{
    if (!poster || !canUseMedia(poster))
        return undefined;
    if (/^data:image\/(?:gif|jpeg|png|webp);base64,[a-z0-9+/=]+$/i.test(poster))
        return poster;
    try {
        const url = new URL(poster);
        return (url.protocol === 'https:' || url.protocol === 'workspace-file:') &&
            !url.username &&
            !url.password
